# description:
# Given an input grid of arbitrary size with colored pixels, identify maximal contiguous runs of a specified target color along rows or columns.
# Each run is a sequence of adjacent cells (4-connectivity) with the same color.
# To produce the output, highlight these runs by changing the color of the run to a new specified color (e.g., teal).

def main(input_grid: np.ndarray, target_color: str, highlight_color: str = Color.TEAL) -> np.ndarray:
    output_grid = input_grid.copy()

    # Check rows for contiguous runs
    for row in range(input_grid.shape[0]):
        start = None
        for col in range(input_grid.shape[1]):
            if input_grid[row, col] == target_color:
                if start is None:
                    start = col
            else:
                if start is not None:
                    # If a run was detected, change its color
                    for i in range(start, col):
                        output_grid[row, i] = highlight_color
                    start = None
        # Check if a run ended at the last column
        if start is not None:
            for i in range(start, input_grid.shape[1]):
                output_grid[row, i] = highlight_color

    # Check columns for contiguous runs
    for col in range(input_grid.shape[1]):
        start = None
        for row in range(input_grid.shape[0]):
            if input_grid[row, col] == target_color:
                if start is None:
                    start = row
            else:
                if start is not None:
                    # If a run was detected, change its color
                    for i in range(start, row):
                        output_grid[i, col] = highlight_color
                    start = None
        # Check if a run ended at the last row
        if start is not None:
            for i in range(start, input_grid.shape[0]):
                output_grid[i, col] = highlight_color

    return output_grid

