    # Generate a grid of arbitrary size with random colors
    n, m = random.randint(5, 10), random.randint(5, 10)
    grid = np.random.choice(list(Color.NOT_BLACK), size=(n, m))

    # Randomly select a target color to find runs of
    target_color = random.choice(list(Color.NOT_BLACK))

    return grid, target_color

