# Each run is a sequence of adjacent cells (4-connectivity) with the same color.
# In the output grid, mark the beginning and end of each detected run with a teal pixel, and leave the rest of the grid unchanged.

def main(input_grid: np.ndarray, target_color: str) -> np.ndarray:
    output_grid = input_grid.copy()

    # Detect runs in rows
    for x in range(input_grid.shape[0]):
        run_start = None
        for y in range(input_grid.shape[1]):
            if input_grid[x, y] == target_color:
                if run_start is None:
                    run_start = y
            else:
                if run_start is not None:
                    # Mark the ends of the run
                    output_grid[x, run_start] = Color.TEAL
                    output_grid[x, y-1] = Color.TEAL
                    run_start = None
        if run_start is not None:
            output_grid[x, run_start] = Color.TEAL
            output_grid[x, input_grid.shape[1]-1] = Color.TEAL

    # Detect runs in columns
    for y in range(input_grid.shape[1]):
        run_start = None
        for x in range(input_grid.shape[0]):
            if input_grid[x, y] == target_color:
                if run_start is None:
                    run_start = x
            else:
                if run_start is not None:
                    # Mark the ends of the run
                    output_grid[run_start, y] = Color.TEAL
                    output_grid[x-1, y] = Color.TEAL
                    run_start = None
        if run_start is not None:
            output_grid[run_start, y] = Color.TEAL
            output_grid[input_grid.shape[0]-1, y] = Color.TEAL

    return output_grid

def generate_input() -> Tuple[np.ndarray, str]:
    # Create a random grid size between 5x5 and 10x10
    n, m = random.randint(5, 10), random.randint(5, 10)
    grid = np.zeros((n, m), dtype=int)

    # Randomly select a target color from Color.NOT_BLACK
    target_color = random.choice(list(Color.NOT_BLACK))

    # Randomly fill the grid with colors, including some contiguous runs of the target color
    for x in range(n):
        for y in range(m):
            if random.random() < 0.3:  # 30% chance to be the target color
                grid[x, y] = target_color
            else:
                grid[x, y] = random.choice(list(Color.NOT_BLACK))

    return grid, target_color

