def main(input_grid: np.ndarray, target_color: str) -> np.ndarray:
    output_grid = input_grid.copy()

    n, m = output_grid.shape

    # Define a function to mark contiguous runs of the target_color
    def mark_runs(grid, color, mark_color):
        # Check rows for contiguous runs
        for i in range(n):
            run_start = None
            for j in range(m):
                if grid[i, j] == color:
                    if run_start is None:
                        run_start = j
                else:
                    if run_start is not None:
                        for k in range(run_start, j):
                            grid[i, k] = mark_color
                        run_start = None
            if run_start is not None:
                for k in range(run_start, m):
                    grid[i, k] = mark_color

        # Check columns for contiguous runs
        for j in range(m):
            run_start = None
            for i in range(n):
                if grid[i, j] == color:
                    if run_start is None:
                        run_start = i
                else:
                    if run_start is not None:
                        for k in range(run_start, i):
                            grid[k, j] = mark_color
                        run_start = None
            if run_start is not None:
                for k in range(run_start, n):
                    grid[k, j] = mark_color

    # Mark runs of the target color with RED
    mark_runs(output_grid, target_color, Color.RED)

    return output_grid

