                    if j - run_start > 1:
                        for k in range(run_start, j):
                            output_grid[i][k] = Color.RED
                    run_start = None
        # Check for run ending at the end of the row
        if run_start is not None and output_grid.shape[1] - run_start > 1:
            for k in range(run_start, output_grid.shape[1]):
                output_grid[i][k] = Color.RED

    # Highlight maximal contiguous runs along each column
    for j in range(output_grid.shape[1]):
        run_start = None
        for i in range(output_grid.shape[0]):
            if output_grid[i][j] == target_color:
                if run_start is None:
                    run_start = i
            else:
                if run_start is not None:
                    if i - run_start > 1:
                        for k in range(run_start, i):
                            output_grid[k][j] = Color.RED
                    run_start = None
        # Check for run ending at the end of the column
        if run_start is not None and output_grid.shape[0] - run_start > 1:
            for k in range(run_start, output_grid.shape[0]):
                output_grid[k][j] = Color.RED

    return output_grid

def generate_input() -> Tuple[np.ndarray, str]:
