def main(input_grid: np.ndarray, target_color: str = Color.BLUE) -> np.ndarray:
    # Create a copy of the input grid for the output
    output_grid = input_grid.copy()

    # Define a distinct color for highlighting
    highlight_color = Color.RED if target_color != Color.RED else Color.YELLOW

    # Scan through rows
    for row in range(input_grid.shape[0]):
        start_idx = None
        for col in range(input_grid.shape[1]):
            if input_grid[row, col] == target_color:
                if start_idx is None:
                    start_idx = col
            else:
                if start_idx is not None:
                    # We have found a run, mark it
                    for i in range(start_idx, col):
                        output_grid[row, i] = highlight_color
                    start_idx = None
        # If the last cell in the row was part of a run, mark it
        if start_idx is not None:
            for i in range(start_idx, input_grid.shape[1]):
                output_grid[row, i] = highlight_color

    # Scan through columns
    for col in range(input_grid.shape[1]):
        start_idx = None
        for row in range(input_grid.shape[0]):
            if input_grid[row, col] == target_color:
                if start_idx is None:
                    start_idx = row
            else:
                if start_idx is not None:
                    # We have found a run, mark it
                    for i in range(start_idx, row):
                        output_grid[i, col] = highlight_color
                    start_idx = None
        # If the last cell in the column was part of a run, mark it
        if start_idx is not None:
            for i in range(start_idx, input_grid.shape[0]):
                output_grid[i, col] = highlight_color

    return output_grid


def generate_input() -> np.ndarray:
    # Random grid size
    n, m = random.randint(5, 15), random.randint(5, 15)

    # Initialize grid with black background
    grid = np.zeros((n, m), dtype=int)

    # Choose a target color randomly. Ensure it's not black
    target_color = random.choice(Color.NOT_BLACK)

    # Randomly fill some positions with the target color to create runs
    num_runs = random.randint(1, min(n, m) // 2)

    for _ in range(num_runs):
        # Choose to create either a horizontal or vertical run
        if random.choice([True, False]):
            # Horizontal run
            row = random.randint(0, n - 1)
            start_col = random.randint(0, m - 2)
            run_length = random.randint(2, m - start_col)
            for col in range(start_col, start_col + run_length):
                grid[row, col] = target_color
        else:
            # Vertical run
            col = random.randint(0, m - 1)
            start_row = random.randint(0, n - 2)
            run_length = random.randint(2, n - start_row)
            for row in range(start_row, start_row + run_length):
                grid[row, col] = target_color

    # Fill the rest of the grid with random colors, but not the target color
    for i in range(n):
        for j in range(m):
            if grid[i, j] == 0:  # If still black
                grid[i, j] = random.choice([c for c in Color.NOT_BLACK if c != target_color])

    return grid

